from hermes_tools import terminal
print(terminal('python3 - <<'PY'
import openpyxl, os
from openpyxl.utils import get_column_letter

out='/root/output/result.xlsx'
wb=openpyxl.load_workbook(out, data_only=False)
ws=wb['Task']
print('Reopened:', out)
print('Sheet names:', wb.sheetnames)

def is_formula(v):
    return isinstance(v, str) and v.startswith('=')

def count_formulas(ranges):
    cells=[]
    missing=[]
    samples=[]
    for min_row, max_row, min_col, max_col in ranges:
        for r in range(min_row, max_row+1):
            for c in range(min_col, max_col+1):
                coord=ws.cell(r,c).coordinate
                v=ws.cell(r,c).value
                if is_formula(v):
                    cells.append(coord)
                    if len(samples) < 8:
                        samples.append((coord,v))
                else:
                    missing.append((coord,v))
    return len(cells), missing, samples

regions = {
    'lookup H12:L17,H19:L24,H26:L31': [(12,17,8,12),(19,24,8,12),(26,31,8,12)],
    'gap H35:L40': [(35,40,8,12)],
    'stats H42:L47': [(42,47,8,12)],
    'weighted H50:L50': [(50,50,8,12)],
}
expected = {
    'lookup H12:L17,H19:L24,H26:L31': 90,
    'gap H35:L40': 30,
    'stats H42:L47': 30,
    'weighted H50:L50': 5,
}
total=0
for name, ranges in regions.items():
    count, missing, samples = count_formulas(ranges)
    total += count
    print(f"{name}: formula count={count}, expected={expected[name]}, missing={len(missing)}")
    if missing:
        print('  Missing/non-formulas:', missing[:10])
    print('  Samples:')
    for coord, formula in samples[:4]:
        print(f"    {coord}: {formula}")

print('\nExplicit sample cells from each formula region:')
for coord in ['H12','I13','L17','H19','L24','H26','L31','H35','J38','L40','H42','I43','J44','K45','L46','H47','H50','L50']:
    print(coord, ws[coord].value)

# Additional structural assertions
assert wb.sheetnames == ['Task', 'Data'], f"Unexpected sheet names: {wb.sheetnames}"
for name, ranges in regions.items():
    count, missing, _ = count_formulas(ranges)
    assert count == expected[name] and not missing, f"{name} failed: {count}, missing {missing[:3]}"
print('\nValidation passed. Total formula count in requested ranges:', total)
print('Output file size bytes:', os.path.getsize(out))
PY', timeout=120)['output'])
